// ===== Builder Base Helper Functions =====

export function getBuilderBaseBySlug(slug: string): BuilderBaseLayout | undefined {
  return builderBaseLayouts.find((b) => b.slug === slug);
}

export function getBuilderBasesByBH(bhLevel: BHLevel): BuilderBaseLayout[] {
  return builderBaseLayouts.filter((b) => b.bhLevel === bhLevel);
}

export function getBuilderBasesByBHAndType(bhLevel: BHLevel, type: BHBaseType): BuilderBaseLayout[] {
  return builderBaseLayouts.filter((b) => b.bhLevel === bhLevel && b.type === type);
}

export function getFeaturedBuilderBases(): BuilderBaseLayout[] {
  return builderBaseLayouts.filter((b) => b.featured);
}

export function getAllBuilderBaseSlugs(): string[] {
  return builderBaseLayouts.map((b) => b.slug);
}

export function getRelatedBuilderBases(slug: string, count: number = 4): BuilderBaseLayout[] {
  const base = getBuilderBaseBySlug(slug);
  if (!base) return [];
  return builderBaseLayouts
    .filter((b) => b.slug !== slug && (b.bhLevel === base.bhLevel || b.type === base.type))
    .sort((a, b) => {
      const aScore = (a.bhLevel === base.bhLevel ? 2 : 0) + (a.type === base.type ? 1 : 0);
      const bScore = (b.bhLevel === base.bhLevel ? 2 : 0) + (b.type === base.type ? 1 : 0);
      return bScore - aScore;
    })
    .slice(0, count);
}

export function getBuilderBaseCountByBH(bhLevel: BHLevel): number {
  return builderBaseLayouts.filter((b) => b.bhLevel === bhLevel).length;
}

export function getAdjacentBuilderBases(slug: string): { prev: BuilderBaseLayout | null; next: BuilderBaseLayout | null } {
  const base = getBuilderBaseBySlug(slug);
  if (!base) return { prev: null, next: null };
  const sameBH = builderBaseLayouts
    .filter((b) => b.bhLevel === base.bhLevel)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  const idx = sameBH.findIndex((b) => b.slug === slug);
  return {
    prev: idx > 0 ? sameBH[idx - 1] : null,
    next: idx < sameBH.length - 1 ? sameBH[idx + 1] : null,
  };
}

// ===== Home Village Helper Functions =====

export function getBaseBySlug(slug: string): BaseLayout | undefined {
  return baseLayouts.find((b) => b.slug === slug);
}

export function getBasesByTH(thLevel: THLevel): BaseLayout[] {
  return baseLayouts.filter((b) => b.thLevel === thLevel);
}

export function getBasesByType(type: BaseType): BaseLayout[] {
  return baseLayouts.filter((b) => b.type === type);
}

export function getBasesByTHAndType(thLevel: THLevel, type: BaseType): BaseLayout[] {
  return baseLayouts.filter((b) => b.thLevel === thLevel && b.type === type);
}

export function getFeaturedBases(): BaseLayout[] {
  return baseLayouts.filter((b) => b.featured);
}

export function getLatestBases(count: number = 6): BaseLayout[] {
  return [...baseLayouts]
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    .slice(0, count);
}

export function getAllBaseSlugs(): string[] {
  return baseLayouts.map((b) => b.slug);
}

export function getRelatedBases(slug: string, count: number = 4): BaseLayout[] {
  const base = getBaseBySlug(slug);
  if (!base) return [];
  return baseLayouts
    .filter((b) => b.slug !== slug && (b.thLevel === base.thLevel || b.type === base.type))
    .sort((a, b) => {
      const aScore = (a.thLevel === base.thLevel ? 2 : 0) + (a.type === base.type ? 1 : 0);
      const bScore = (b.thLevel === base.thLevel ? 2 : 0) + (b.type === base.type ? 1 : 0);
      return bScore - aScore;
    })
    .slice(0, count);
}

export function getAdjacentBases(slug: string): { prev: BaseLayout | null; next: BaseLayout | null } {
  const base = getBaseBySlug(slug);
  if (!base) return { prev: null, next: null };
  // Get bases of the same TH level, sorted by date
  const sameTH = baseLayouts
    .filter((b) => b.thLevel === base.thLevel)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  const idx = sameTH.findIndex((b) => b.slug === slug);
  return {
    prev: idx > 0 ? sameTH[idx - 1] : null,
    next: idx < sameTH.length - 1 ? sameTH[idx + 1] : null,
  };
}

export function getBaseCountByTH(thLevel: THLevel): number {
  return baseLayouts.filter((b) => b.thLevel === thLevel).length;
}

export function formatViews(views: number): string {
  if (views >= 1000) return `${(views / 1000).toFixed(1)}K`;
  return String(views);
}
